"""Boundary counterexamples from the independent P0 detector review, generated bytes only."""
import io
import json
from urllib.error import HTTPError

import pyarrow as pa
import pyarrow.parquet as pq
import pytest
from test_hub_content import remote  # noqa: F401 -- shared generated Hub fixture
from test_video_index import KEY, _RangeOpener, codes, dataset, movie

from policy_doctor import hub
from policy_doctor.artifacts import InputError
from policy_doctor.video_index import HEADER_INDEX, _episode_rows, check_video_index, header_timing


def metadata(root):
    return root / "meta/episodes/chunk-000/file-000.parquet"


def update_info(root, **values):
    path = root / "meta/info.json"
    info = json.loads(path.read_text())
    info.update(values)
    path.write_text(json.dumps(info))


def test_forged_sidecar_cannot_hide_actual_video_overrun(tmp_path):
    root = dataset(tmp_path, [(3, 0, 0.0), (2, 0, 0.6)], {0: 3}, with_data=True)
    rel = f"videos/{KEY}/chunk-000/file-000.mp4"
    (root / ".roboclue").mkdir()
    (root / HEADER_INDEX).write_text(json.dumps({"listing": [rel], "headers": {
        rel: {"status": "parsed", "sample_count": 500, "last_sample_start_s": 99.8, "end_s": 100.0}}}))
    assert "video.interval_past_end" in codes(check_video_index(root)[0])


@pytest.mark.parametrize("mode", ["relative_escape", "absolute_escape", "symlink_ancestor"])
def test_media_path_cannot_open_outside_root(tmp_path, monkeypatch, mode):
    root = dataset(tmp_path, [(3, 0, 0.0)], {0: 3})
    outside = tmp_path / "outside.mp4"
    outside.write_bytes(movie(3))
    if mode == "relative_escape":
        template = "../outside.mp4"
    elif mode == "absolute_escape":
        template = str(outside)
    else:
        (root / "alias").symlink_to(tmp_path, target_is_directory=True)
        template = "alias/outside.mp4"
    update_info(root, video_path=template)
    monkeypatch.setattr("policy_doctor.video_index._LocalMedia", lambda path: pytest.fail(f"Unsafe open: {path}"))
    try:
        findings, coverage = check_video_index(root)
    except InputError:
        return
    assert findings == [] and coverage["video_index_details"]["status"] == "unknown"


def test_row_budget_stops_before_parquet_materialization(tmp_path, monkeypatch):
    root = dataset(tmp_path, [(3, 0, 0.0), (2, 0, 0.6)], {0: 3})
    monkeypatch.setattr(pq, "read_table", lambda *a, **k: pytest.fail("Must not materialize an unchecked table"))
    findings, coverage = check_video_index(root, max_rows=1)
    assert findings == [] and coverage["video_index_details"]["status"] == "unknown"
    assert "row" in coverage["video_index"]


def test_expansion_budget_stops_before_any_batch_read(tmp_path, monkeypatch):
    root = dataset(tmp_path, [(3, 0, 0.0)], {0: 3})
    keys = [f"observation.images.camera_{i}" for i in range(10)]
    update_info(root, features={key: {"dtype": "video"} for key in keys})
    count = 25000
    columns = {"episode_index": pa.array(range(count)), "length": pa.array([3] * count)}
    for key in keys:
        for name in ("chunk_index", "file_index", "from_timestamp", "to_timestamp"):
            columns[f"videos/{key}/{name}"] = pa.array([0.0 if name.endswith("timestamp") else 0] * count)
    pq.write_table(pa.table(columns), metadata(root), compression="zstd", use_dictionary=False)
    def forbidden(*a, **k):
        pytest.fail("Expanded metadata must be refused before iter_batches")
    monkeypatch.setattr(pq.ParquetFile, "iter_batches", forbidden)
    findings, coverage = check_video_index(root)
    assert findings == [] and "budget" in coverage["video_index"]


@pytest.mark.parametrize("change", ["string_timestamp", "nan_timestamp", "missing_episode", "bad_features", "bool_index"])
def test_malformed_metadata_has_structured_unknown(tmp_path, change):
    root = dataset(tmp_path, [(3, 0, 0.0)], {0: 3})
    if change == "bad_features":
        update_info(root, features=[1])
    else:
        rows = pq.read_table(metadata(root)).to_pylist()
        if change == "missing_episode":
            rows[0].pop("episode_index")
        elif change == "bool_index":
            rows[0][f"videos/{KEY}/file_index"] = True
        else:
            rows[0][f"videos/{KEY}/from_timestamp"] = "bad" if change == "string_timestamp" else float("nan")
        pq.write_table(pa.Table.from_pylist(rows), metadata(root))
    findings, coverage = check_video_index(root)
    assert findings == [] and coverage["video_index_details"]["status"] == "unknown"


def test_metadata_symlink_ancestor_never_reads(tmp_path, monkeypatch):
    root = dataset(tmp_path, [(3, 0, 0.0)], {0: 3})
    directory = root / "meta/episodes/chunk-000"
    outside = tmp_path / "outside"
    directory.rename(outside)
    directory.symlink_to(outside, target_is_directory=True)
    monkeypatch.setattr(pq, "ParquetFile", lambda *a, **k: pytest.fail("Symlink metadata read"))
    findings, coverage = check_video_index(root)
    assert findings == [] and coverage["video_index_details"]["status"] == "unknown"


def test_explicit_no_video_headers_never_opens_local_media(tmp_path, monkeypatch):
    root = dataset(tmp_path, [(3, 0, 0.0)], {0: 3})
    monkeypatch.setattr("policy_doctor.video_index._LocalMedia", lambda path: pytest.fail("Unexpected media read"))
    findings, coverage = check_video_index(root, video_headers=False)
    assert findings == [] and coverage["video_index_details"]["status"] == "partial"
    assert coverage["video_index_details"]["files_unread"] == 1


def test_exact_remote_ranges_never_intersect_sample_payload(tmp_path, monkeypatch):
    raw = movie(9000)
    opener = _RangeOpener(raw)
    monkeypatch.setattr(hub, "_opener", lambda: opener)
    media = hub._HubRangeMedia("https://huggingface.co/datasets/o/d/resolve/" + "a" * 40 + "/v.mp4",
                               len(raw), hub._HeaderBudget())
    assert header_timing(media)["sample_count"] == 9000
    begin, end = raw.index(b"mdat") + 4, raw.index(b"moov") - 4
    assert all(last < begin or first >= end for first, last in opener.calls)


def test_redirect_obeys_request_limit_before_second_call(monkeypatch):
    class Opener:
        calls = 0

        def open(self, request, timeout=None):
            self.calls += 1
            raise HTTPError(request.full_url, 302, "Redirect", {"Location": "https://example.hf.co/v.mp4"}, io.BytesIO())
    opener = Opener()
    monkeypatch.setattr(hub, "_opener", lambda: opener)
    budget = hub._HeaderBudget(requests=1)
    media = hub._HubRangeMedia("https://huggingface.co/datasets/o/d/resolve/" + "a" * 40 + "/v.mp4", 100, budget)
    with pytest.raises(InputError, match="request or time bound"):
        media.read(0, 8)
    assert opener.calls == budget.used_requests == 1


@pytest.mark.parametrize("suffix", ["?token=x", "#fragment"])
def test_canonical_range_start_refuses_query_or_fragment(monkeypatch, suffix):
    monkeypatch.setattr(hub, "_opener", lambda: pytest.fail("Invalid initial URL attempted HTTP"))
    media = hub._HubRangeMedia("https://huggingface.co/datasets/o/d/resolve/" + "a" * 40 + "/v.mp4" + suffix,
                               100, hub._HeaderBudget())
    with pytest.raises(InputError):
        media.read(0, 8)


def test_one_unavailable_header_does_not_erase_another_definite_overrun(tmp_path):
    root = dataset(tmp_path, [(3, 0, 0.0), (2, 1, 0.0)], {0: 3, 1: 2}, write_videos=False)
    a, b = [f"videos/{KEY}/chunk-000/file-{i:03d}.mp4" for i in range(2)]
    headers = {a: {"status": "parsed", "sample_count": 1, "last_sample_start_s": 0.0},
               b: {"status": "unavailable", "reason": "request budget"}}
    findings, coverage = check_video_index(root, listing={a, b}, headers=headers)
    assert "video.interval_past_end" in codes(findings)
    assert coverage["video_index_details"]["status"] == "partial"
    assert coverage["video_index_details"]["finding_counts"]["error"] == 1


def test_episode_reader_accepts_caller_file_bound(tmp_path):
    root = dataset(tmp_path, [(3, 0, 0.0)], {0: 3})
    other = root / "meta/episodes/chunk-000/file-001.parquet"
    other.write_bytes(metadata(root).read_bytes())
    with pytest.raises(ValueError, match="file budget"):
        _episode_rows(root, [KEY], max_files=1)


def test_live_snapshot_passes_observations_in_memory_without_creating_sidecar(remote):  # noqa: F811
    with hub.resolve_dataset_content("hf://org/data", fetch=True) as view:
        assert view.video_context == {"listing": {"videos/chunk-000/file-000.mp4"}, "headers": None}
        assert not (view.root / ".roboclue").exists()


def test_header_intake_keeps_per_file_failures_as_unknown_observations(tmp_path, monkeypatch):
    root = dataset(tmp_path, [(3, 0, 0.0), (3, 1, 0.0)], {0: 3, 1: 3})
    names = [f"videos/{KEY}/chunk-000/file-{i:03d}.mp4" for i in range(2)]
    def timing(media):
        if media.url.endswith("file-000.mp4"):
            raise hub.HubUnavailable("bounded header failure")
        return {"status": "parsed", "sample_count": 3, "last_sample_start_s": 0.4}
    monkeypatch.setattr("policy_doctor.video_index.header_timing", timing)
    provenance = {}
    headers = hub._video_header_intake(root, "org/data", "a" * 40, dict.fromkeys(names, 100), provenance)
    assert headers[names[0]]["status"] == "unavailable"
    assert headers[names[1]]["status"] == "parsed"
    assert provenance["video_headers"]["files"] == 2


def test_header_intake_honors_row_budget_before_http(tmp_path, monkeypatch):
    root = dataset(tmp_path, [(3, 0, 0.0), (3, 1, 0.0)], {0: 3, 1: 3})
    monkeypatch.setattr(hub, "_opener", lambda: pytest.fail("Over-budget metadata attempted network"))
    with pytest.raises(ValueError, match="row"):
        hub._video_header_intake(root, "org/data", "a" * 40, {}, {}, max_rows=1)


def test_header_timeout_uses_remaining_deadline(monkeypatch):
    raw = movie(3)
    parent = _RangeOpener(raw)
    class Opener:
        def open(self, request, timeout=None):
            assert timeout <= 0.5
            return parent.open(request, timeout)
    budget = hub._HeaderBudget()
    budget.deadline = 100.5
    monkeypatch.setattr(hub.time, "monotonic", lambda: 100.0)
    monkeypatch.setattr(hub, "_opener", Opener)
    media = hub._HubRangeMedia("https://huggingface.co/datasets/o/d/resolve/" + "a" * 40 + "/v.mp4", len(raw), budget)
    assert media.read(0, 8) == raw[:8]
